// src/vanilla/stories/gallery.ts
var storySelect = document.querySelector("#story");
var themeSelect = document.querySelector("#theme");
var reactFrame = document.querySelector("#react-frame");
var vanillaFrame = document.querySelector("#vanilla-frame");
for (const entry of manifest_default) {
  const option = document.createElement("option");
  option.value = entry.id;
  option.textContent = `${entry.title} / ${entry.name}`;
  storySelect.append(option);
}
function showStory() {
  const entry = manifest_default.find((item) => item.id === storySelect.value) ?? manifest_default[0];
  const theme = themeSelect.value;
  document.documentElement.dataset.theme = theme;
  reactFrame.src = `../../../storybook-static/iframe.html?id=${encodeURIComponent(entry.id)}&viewMode=story&globals=theme:${encodeURIComponent(theme)}`;
  vanillaFrame.src = entry.html;
  vanillaFrame.onload = () => {
    if (vanillaFrame.contentDocument) vanillaFrame.contentDocument.documentElement.dataset.theme = theme;
  };
}
storySelect.addEventListener("change", showStory);
themeSelect.addEventListener("change", showStory);
showStory();
